    points = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == 8]
    if not points:
        return [row[:] for row in grid]
    r0, r1 = min(r for r, c in points), max(r for r, c in points)
    c0, c1 = min(c for r, c in points), max(c for r, c in points)
    height, width = r1-r0+1, c1-c0+1

    # Reflect the marked rectangle across the grid's central symmetry axes.
    row_source = (31-r1, 31-r0)
    col_source = (31-c1, 31-c0)
    if row_source[0] >= 0 and row_source[1] < h and all(
        grid[r][c] != 8 for r in range(row_source[0], row_source[1]+1)
        for c in range(c0, c1+1)
    ):
        return [grid[row_source[1]-(r-r0)][c0:c1+1] for r in range(r0, r1+1)]
    if col_source[0] >= 0 and col_source[1] < w and all(
        grid[r][c] != 8 for r in range(r0, r1+1)
